self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url),scope=new URL(self.registration.scope);if(event.request.method!=='GET'||url.origin!==scope.origin||!url.pathname.startsWith(scope.pathname))return;
 const relative='./'+url.pathname.slice(scope.pathname.length);if(!FILES.includes(relative)&&event.request.mode!=='navigate')return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(event.request);if(response.ok&&FILES.includes(relative))await cache.put(relative,response.clone());return response;}catch{const stored=await cache.match(relative);return stored||(event.request.mode==='navigate'?await cache.match('./index.html'):Response.error());}})());
});
self.addEventListener('message',event=>{if(event.data!=='VERIFY_OFFLINE')return;event.waitUntil(caches.open(CACHE).then(async cache=>{const all=await Promise.all(FILES.map(f=>cache.match(f)));if(all.every(Boolean))event.source?.postMessage('OFFLINE_READY');}));});
